sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float focusPos;
uniform float focusWidth;
uniform float feather;
uniform float angle;
uniform float satBoost;
uniform float contrastBoost;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 sat3(float3 c, float s) {
    return mix(float3(dot(c, float3(0.2126, 0.7152, 0.0722))), c, s);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 b = float4(blurred.eval(coord));
    float a = radians(angle);
    float2 n = float2(sin(a), cos(a));
    float d = abs(dot(coord / size - float2(0.5), n) - (focusPos - 0.5));
    float mask = smoothstep(focusWidth * 0.5, focusWidth * 0.5 + feather, d);
    float4 r = mix(c, b, mask);
    float3 s = unp(r);
    s = sat3(s, 1.0 + satBoost * mask);
    s = (s - 0.5) * (1.0 + contrastBoost * mask) + 0.5;
    return fin(c, float4(saturate(s) * r.a, r.a), opacity);
}
